export function validateCheckoutResponse(response, startedAt, now = Date.now()) {
  return { checkoutId: "", elapsedMs: 0 };
}

import assert from "node:assert/strict";
import { validateCheckoutResponse } from "./canary.js";

const valid = validateCheckoutResponse(
  { statusCode: 200, headers: { "content-type": "application/json; charset=utf-8" }, body: JSON.stringify({ checkoutId: "chk-1042", status: "ready" }) },
  1000,
  1280,
);
assert.deepEqual(valid, { checkoutId: "chk-1042", elapsedMs: 280 });

for (const response of [
  { statusCode: 503, headers: { "content-type": "application/json" }, body: "{}" },
  { statusCode: 200, headers: { "content-type": "text/html" }, body: "<html></html>" },
  { statusCode: 200, headers: { "content-type": "application/json" }, body: JSON.stringify({ status: "ready" }) },
  { statusCode: 200, headers: { "content-type": "application/json" }, body: JSON.stringify({ checkoutId: "chk-1", status: "pending" }) },
]) {
  assert.throws(() => validateCheckoutResponse(response, 1000, 1100));
}

console.log("canary contract passed");
